mapper.select:
select c.*, cl.level as leader_level, cl.tags as leader_tags
from club c
left join club_leader cl on cl.member_id = c.member_id and cl.del_flag = 0

    c.del_flag = 0
     and c.name like concat('%', #{name}, '%')
     and c.member_id = #{memberId}
     and c.category_id = #{categoryId}
     and c.status = #{status}

order by c.create_time desc

select count(*) from club
where del_flag = 0 and status in (0, 1) and trim(name) = #{name}
 and member_id != #{memberId}
 and id != #{excludeClubId}
